        engineeringData: { blockDesign: "Closed-deck Aluminum alloy block with wire-arc sprayed iron cylinder linings. The 'B' in B48B20B denotes longitudinal mounting for the classic Rear-Wheel Drive layout. Part of the highly successful modular B-series family, featuring incredible structural rigidity compared to older open-deck designs.", crankshaft: "Forged Steel, supported by 5 main bearings. The 'B' high-output variant features a heavily reinforced crankshaft and larger main bearings.", pistonSpeed: "14.2 m/s @ 6000 RPM.", alternator: "150A Valeo.", rotatingAssembly: { pistonConstruction: "Cast Aluminum alloy. The '20B' high-output variant uses robust pistons with a lower 10.2:1 compression ratio, making it highly resistant to extreme boost pressures and detonation.", wristPinDiameter: "22 mm.", connectingRodLength: "148 mm.", rodBoltSize: "M8 stretch bolts.", crankMainJournal: "50.0 mm.", crankRodJournal: "45.0 mm.", rodRatio: "1.56." }, cylinderHead: { combustionChamberVol: "Optimized pent-roof design for 10.2:1 compression.", intakePortFlow: "High-velocity tumble ports. Features BMW's 4th Generation Valvetronic system integrated directly into the cylinder head, controlling intake valve lift to eliminate throttle body pumping losses.", valveSizes: "Intake: 30.0 mm / Exhaust: 28.0 mm.", valveStemDiameter: "5.0 mm.", camshaftDuration: "Double VANOS on both intake and exhaust, plus continuous Valvetronic.", lifterType: "Hydraulic lifters with intermediate levers.", specialFeature: "The timing chain is mounted at the REAR of the engine to save space and improve pedestrian safety." }, oilAndCooling: { oilSquirters: "Yes, dedicated under-piston cooling jets.", oilPumpType: "Map-controlled variable volume gear pump.", thermostatOpening: "105°C Electronic map-controlled Heat Management Module.", oilCooler: "Water-to-oil heat exchanger attached to the filter housing." }, fuelSystem: { systemType: "High-Pressure Direct Injection (HPI).", maxPressure: "200 Bar.", injectors: "4x Bosch Solenoid Injectors (Highly reliable)." }, tuningLimits: { maxSafeTorqueStock: "500 Nm.", maxSafePowerStock: "400 hp.", maxSafeRPM: "6500 RPM.", weakestLink: "Plastic Charge Pipe, ZF 8-Speed torque limit (requires xHP flash for extreme torque)." }, electrical: { coils: "Push-down 3-wire Active Coils.", ecu: "Bosch MEVD17.2.G." } },
