        engineeringData: { blockDesign: "Open-deck Aluminum alloy block with cast-iron cylinder liners. Highly refined evolution of the N54, designed for superior efficiency, smoother power delivery, and massively improved peripheral reliability.", crankshaft: "Forged/Reinforced Steel. The 'O0' top-tier variant utilized in M Performance models features a significantly stronger crankshaft specifically engineered to handle continuous high-RPM track abuse and increased power outputs.", pistonSpeed: "18.3 m/s @ 7000 RPM.", alternator: "180A Valeo.", rotatingAssembly: { pistonConstruction: "Cast Aluminum alloy with specialized crowns for direct injection.", wristPinDiameter: "22 mm.", connectingRodLength: "144 mm.", rodBoltSize: "M9 stretch bolts.", crankMainJournal: "56.0 mm.", crankRodJournal: "50.0 mm.", rodRatio: "1.64." }, cylinderHead: { combustionChamberVol: "Optimized pent-roof design tailored for the 10.2:1 compression ratio.", intakePortFlow: "High-velocity tumble ports. The N55 utilizes Valvetronic, allowing the intake valves to act directly as the throttle for instant response and better fuel economy.", valveSizes: "Intake: 32.0 mm / Exhaust: 28.0 mm.", valveStemDiameter: "5.0 mm.", camshaftDuration: "Double VANOS on both intake and exhaust camshafts, plus continuous Valvetronic lift control.", lifterType: "Hydraulic lifters with intermediate levers for Valvetronic.", specialFeature: "Direct injection utilizes highly reliable Bosch solenoids instead of fragile piezo units." }, oilAndCooling: { oilSquirters: "Yes, dedicated high-flow under-piston cooling jets.", oilPumpType: "Map-controlled variable volume gear pump. Highly sensitive to air pockets; requires strict priming procedure.", thermostatOpening: "97°C Map-controlled electronic thermostat.", oilCooler: "External air-to-oil cooler mounted in the passenger side wheel well." }, fuelSystem: { systemType: "High-Pressure Direct Injection (HPI).", maxPressure: "200 Bar generated by the mechanical HPFP.", injectors: "6x Bosch Solenoid Injectors (Highly reliable)." }, tuningLimits: { maxSafeTorqueStock: "600 Nm.", maxSafePowerStock: "450 hp.", maxSafeRPM: "7200 RPM.", weakestLink: "Plastic Charge Pipe, Cast Pistons, Rod Bearings (under poor lubrication)." }, electrical: { coils: "Push-down 3-wire Active Coils.", ecu: "Bosch MEVD17.2.G." } },
        recommendedParts: { description: "Crucial preventative maintenance parts to maximize the lifespan and reliability of the EWG N55 inline-6.", parts: [ { category: "Aluminum Charge Pipe", brand: "VRSF / Evolution Racewerks", note: "CRITICAL: Replaces the exploding factory plastic pipe." }, { category: "Electric Water Pump", brand: "Pierburg / VDO", note: "CRITICAL: Replace proactively every 100k km before it fails." }, { category: "Oil Filter Housing Gasket", brand: "Elring", note: "CRITICAL: Stops catastrophic oil leaks onto the serpentine belt." }, { category: "Ignition Coils", brand: "Eldor", note: "Upgrade to the latest revision for reliable high-boost performance." }, { category: "Spark Plugs", brand: "NGK 1-Step Colder", note: "Mandatory for tuned vehicles to prevent spark blowout." }, { category: "Valve Cover Kit", brand: "Genuine BMW", note: "Replace the entire plastic cover to cure internal PCV failure." }, { category: "Rod Bearing Kit", brand: "ACL / King", note: "Proactive upgrade for tracked or highly tuned vehicles." }, { category: "Valvetronic Motor", brand: "VDO", note: "Replace if erratic idling or throttle response issues occur." } ] },
