          automatics: [ { name: "8-Speed Steptronic Sport (ZF 8HP50)", torqueLimit: "500 Nm", oilType: "ZF Lifeguard 8", note: "The absolute gold standard of automatic transmissions. Flawless, lightning-fast shifts that rival dual-clutch systems. Can handle up to 600Nm reliably with xHP transmission tuning software." } ]
