        engineeringData: { blockDesign: "Closed-deck Aluminum alloy block with wire-arc sprayed iron cylinder linings. The B58 is an absolute engineering marvel, offering massive structural rigidity specifically designed to handle extreme combustion pressures without cylinder distortion.", crankshaft: "Forged Steel, supported by 7 main bearings. Immensely strong.", pistonSpeed: "15.9 m/s @ 7000 RPM.", alternator: "180A Valeo.", rotatingAssembly: { pistonConstruction: "Cast Aluminum alloy tailored for direct injection, incredibly thick and durable. The M0 variant runs a versatile 11.0:1 compression ratio.", wristPinDiameter: "22 mm.", connectingRodLength: "148 mm.", rodBoltSize: "M9 stretch bolts.", crankMainJournal: "50.0 mm.", crankRodJournal: "45.0 mm.", rodRatio: "1.56." }, cylinderHead: { combustionChamberVol: "Optimized pent-roof design for 11.0:1 compression.", intakePortFlow: "High-velocity tumble ports. Features BMW's 4th Generation Valvetronic system integrated directly into the cylinder head, controlling intake valve lift to eliminate throttle body pumping losses.", valveSizes: "Intake: 30.0 mm / Exhaust: 28.0 mm.", valveStemDiameter: "5.0 mm.", camshaftDuration: "Double VANOS on both intake and exhaust, plus continuous Valvetronic.", lifterType: "Hydraulic lifters with intermediate levers.", specialFeature: "The timing chain is mounted at the REAR of the engine, alongside the VANOS actuators, to save space." }, oilAndCooling: { oilSquirters: "Yes, dedicated high-flow under-piston cooling jets.", oilPumpType: "Map-controlled variable volume gear pump.", thermostatOpening: "105°C Electronic map-controlled Heat Management Module.", oilCooler: "Water-to-oil heat exchanger attached to the filter housing." }, fuelSystem: { systemType: "High-Pressure Direct Injection (HPI).", maxPressure: "250 Bar generated by the mechanical HPFP.", injectors: "6x Bosch Solenoid Injectors (Highly reliable)." }, tuningLimits: { maxSafeTorqueStock: "700 Nm.", maxSafePowerStock: "600 hp.", maxSafeRPM: "7200 RPM.", weakestLink: "High-Pressure Fuel Pump (HPFP runs out of flow at ~480hp), Factory Turbo limits." }, electrical: { coils: "Push-down 3-wire Active Coils.", ecu: "Bosch MG1CS024." } },
        recommendedParts: { description: "Crucial preventative maintenance parts to maximize the lifespan and extreme power potential of the B58 inline-6.", parts: [ { category: "Upgraded PCV Diaphragm Kit", brand: "Vaico / Ross Racing", note: "CRITICAL: Replaces the failing factory membrane, saving the rear main seal." }, { category: "Coolant Expansion Tank Cap", brand: "Genuine BMW", note: "Proactively replace to cure mysterious coolant evaporation issues." }, { category: "Aluminum Charge Pipe", brand: "FTP / VRSF", note: "CRITICAL: Replaces the factory plastic pipe before applying ECU tunes." }, { category: "Spark Plugs", brand: "NGK Laser Iridium (1-Step Colder)", note: "Mandatory for tuned vehicles to prevent spark blowout." }, { category: "Ignition Coils", brand: "Eldor", note: "Upgrade to the latest revision for reliable high-boost performance." }, { category: "TU High-Pressure Fuel Pump", brand: "Genuine BMW (Supra Pump)", note: "The most popular upgrade for Stage 2+ tunes running E85 blends." }, { category: "Engine Oil Filter", brand: "Genuine BMW", note: "CRITICAL: Use ONLY Genuine BMW to prevent the filter from disintegrating." }, { category: "Heat Management Module", brand: "Genuine BMW", note: "Replace immediately if coolant temperatures behave erratically." } ] },
