          oilAndFilters: [ { interval: "8,000 km", timeLimit: "1 year", task: "Oil & Filter Change", details: "BMW Longlife-04 synthetic strictly. Frequent changes are absolutely vital. CRITICAL: Pull the oil filter straight up gently to prevent it from snapping inside the housing.", parts: ["6.5L Oil", "BMW Filter"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "110 EUR" }, { interval: "30,000 km", timeLimit: "2 years", task: "Engine Air Filter", details: "Replace paper element or clean aftermarket intakes.", parts: ["Air Filter"], importance: "High", laborDifficulty: "Easy", estimatedCost: "35 EUR" }, { interval: "30,000 km", timeLimit: "1 year", task: "Cabin Filter", details: "Activated carbon replacement.", parts: ["Cabin Filter"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "30 EUR" } ],
          ignitionAndEngine: [ { interval: "30,000 km", timeLimit: "3 years", task: "Spark Plugs", details: "CRITICAL: Tuned B58s eat spark plugs. Replace frequently and gap to 0.022 inches.", parts: ["6x NGK Plugs"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "120 EUR" }, { interval: "60,000 km", timeLimit: "5 years", task: "Ignition Coils", details: "Proactive replacement of degrading coil packs to prevent boost misfires.", parts: ["6x Eldor Coils"], importance: "High", laborDifficulty: "Easy", estimatedCost: "250 EUR" }, { interval: "100,000 km", timeLimit: "6 years", task: "Walnut Blasting Carbon Clean", details: "Physically clean carbon buildup from intake valves. Completely restores lost airflow. B58 builds carbon slower than N55, but it still occurs.", parts: ["Intake Gaskets", "Walnut Media"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "350 EUR" }, { interval: "60,000 km", timeLimit: "4 years", task: "PCV Valve Inspection", details: "Listen for high-pitched whistling. Proactively replace the diaphragm to prevent rear main seal blowout.", parts: ["PCV Kit"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "80 EUR" } ],
