          coolingAndHvac: [ { interval: "100,000 km", timeLimit: "5 years", task: "Coolant Flush (Both Circuits)", details: "Drain and refill G48 coolant in both the main engine circuit and the charge-air cooler circuit.", parts: ["10.4L G48"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "90 EUR" }, { interval: "100,000 km", timeLimit: "6 years", task: "Heat Management Module Check", details: "Inspect the electronic water valving module for leaks or codes.", parts: ["Diagnostic"], importance: "High", laborDifficulty: "Easy", estimatedCost: "0 EUR" }, { interval: "4 Years", timeLimit: "4 years", task: "A/C Recharge", details: "Evacuate and recharge R134a.", parts: ["Refrigerant"], importance: "Medium", laborDifficulty: "Intermediate", estimatedCost: "80 EUR" } ],
