          automatics: [ { name: "8-Speed Steptronic (ZF 8HP50)", torqueLimit: "500 Nm", oilType: "ZF Lifeguard 8", note: "One of the best automatic transmissions ever made. Flawless, lightning-fast shifts perfectly suited for the RWD layout. The 8HP50 handles tuned B47 torque easily. Requires strict fluid and filter pan replacement every 80,000 km." } ]
