        engineeringData: { blockDesign: "Closed-deck Aluminum alloy block with wire-arc sprayed iron cylinder linings. Part of the highly successful modular B-series family. Mounted longitudinally for the classic RWD layout. Features acoustic dampening to reduce diesel clatter significantly.", crankshaft: "Forged Steel, supported by 5 main bearings, highly robust.", pistonSpeed: "13.3 m/s @ 4000 RPM.", alternator: "150A Valeo.", rotatingAssembly: { pistonConstruction: "Cast Aluminum alloy with internal oil cooling galleries and a specialized combustion bowl in the crown.", wristPinDiameter: "26 mm.", connectingRodLength: "144 mm.", rodBoltSize: "M9 stretch bolts.", crankMainJournal: "55.0 mm.", crankRodJournal: "50.0 mm.", rodRatio: "1.66." }, cylinderHead: { combustionChamberVol: "Flat head design; combustion occurs entirely within the piston bowl.", intakePortFlow: "16-valve DOHC. Features highly efficient EGR routing integrated into the head and swirl flaps in the manifold.", valveSizes: "Intake: 27.2 mm / Exhaust: 24.6 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Fixed timing.", lifterType: "Hydraulic lifters with low-friction roller rockers.", specialFeature: "The timing chain is mounted at the REAR of the engine to save space, but unlike the N47, it rarely requires service." }, oilAndCooling: { oilSquirters: "Yes, dedicated high-pressure under-piston cooling jets.", oilPumpType: "Map-controlled variable volume gear pump.", thermostatOpening: "88°C Mechanical.", oilCooler: "Water-to-oil heat exchanger attached to the filter housing." }, fuelSystem: { systemType: "Bosch EDC17 Common Rail Direct Injection.", maxPressure: "2000 Bar (CP4.1 Pump).", injectors: "4x Solenoid Injectors (Highly reliable)." }, tuningLimits: { maxSafeTorqueStock: "450 Nm.", maxSafePowerStock: "240 hp.", maxSafeRPM: "4800 RPM.", weakestLink: "Dual Mass Flywheel, Factory Turbocharger flow limits, High-Pressure Fuel Pump (under poor lubrication)." }, electrical: { coils: "N/A (Compression Ignition).", ecu: "Bosch EDC17C50." } },
        recommendedParts: { description: "Crucial preventative maintenance parts to maximize the lifespan of the B47 diesel engine.", parts: [ { category: "EGR Cooler", brand: "Genuine BMW", note: "CRITICAL: Monitor for internal coolant consumption; a known severe fire hazard." }, { category: "Fuel Filter", brand: "Mann-Filter", note: "CRITICAL: Clean fuel is the only thing lubricating the fragile HPFP." }, { category: "Glow Plugs", brand: "Beru / Bosch", note: "Failed glow plugs will prevent the crucial DPF regeneration cycles." }, { category: "Vibration Damper (Crank Pulley)", brand: "Corteco / Gates", note: "Replace if rubber shows cracking; prevents belt shredding." }, { category: "Injector Copper Seals", brand: "Elring", note: "Replace if a chuffing noise or exhaust smell is present in the cabin." }, { category: "Engine Oil Filter", brand: "Mann-Filter", note: "Use exclusively OEM quality to protect the delicate timing chain." }, { category: "DPF Differential Sensor", brand: "Bosch", note: "Prone to failure, causing false DPF clogged readings." }, { category: "Intake Manifold Gaskets", brand: "Elring", note: "Required when removing the manifold for physical carbon cleaning." } ] },
