          ignitionAndEngine: [ { interval: "80,000 km", timeLimit: "5 years", task: "Glow Plugs", details: "Replace to ensure perfect cold starts and active DPF regens.", parts: ["4x Beru Plugs"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "120 EUR" }, { interval: "100,000 km", timeLimit: "Unlimited", task: "EGR & Intake Clean", details: "Remove intake manifold and clean EGR carbon sludge.", parts: ["Gaskets", "Cleaner"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "300 EUR" }, { interval: "150,000 km", timeLimit: "Unlimited", task: "DPF Ash Cleaning", details: "Remove DPF and send for professional ash flushing.", parts: ["Exhaust Gaskets"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "400 EUR" }, { interval: "150,000 km", timeLimit: "8 years", task: "Vibration Damper Check", details: "Inspect the main crank pulley for rubber cracking. Replace immediately to prevent belt shedding.", parts: ["Corteco Pulley"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "180 EUR" } ],
