        engineeringData: { blockDesign: "Cast Aluminum alloy block with cast-iron cylinder liners. Highly refined and exceptionally lightweight compared to older diesels. Crucially, the timing chain was moved to the rear of the engine (gearbox side) to improve pedestrian safety and weight distribution, creating a massive maintenance nightmare.", crankshaft: "Forged Steel, supported by 5 main bearings, highly robust.", pistonSpeed: "13.3 m/s @ 4000 RPM.", alternator: "150A Valeo.", rotatingAssembly: { pistonConstruction: "Cast Aluminum alloy with internal oil cooling galleries and a specialized combustion bowl in the crown.", wristPinDiameter: "26 mm.", connectingRodLength: "144 mm.", rodBoltSize: "M9 stretch bolts.", crankMainJournal: "55.0 mm.", crankRodJournal: "50.0 mm.", rodRatio: "1.66." }, cylinderHead: { combustionChamberVol: "Flat head design; combustion occurs entirely within the piston bowl.", intakePortFlow: "16-valve DOHC. Features swirl flaps in the intake manifold to increase air velocity and mixing at low RPMs.", valveSizes: "Intake: 27.2 mm / Exhaust: 24.6 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Fixed timing. Driven by the notorious rear-mounted timing chain.", lifterType: "Hydraulic lifters with low-friction roller rockers.", specialFeature: "Integrated high-pressure EGR routing directly into the cylinder head." }, oilAndCooling: { oilSquirters: "Yes, dedicated high-pressure under-piston cooling jets.", oilPumpType: "Chain-driven gear pump located in the oil pan.", thermostatOpening: "88°C Mechanical.", oilCooler: "Water-to-oil heat exchanger." }, fuelSystem: { systemType: "Bosch EDC17 Common Rail.", maxPressure: "1800 Bar.", injectors: "4x Solenoid injectors." }, tuningLimits: { maxSafeTorqueStock: "480 Nm (Limited primarily by the clutch/DMF).", maxSafePowerStock: "260 hp.", maxSafeRPM: "4800 RPM.", weakestLink: "Rear Timing Chain, Bosch CP4 HPFP, Dual Mass Flywheel." }, electrical: { coils: "N/A (Compression Ignition).", ecu: "Bosch EDC17." } },
        recommendedParts: { description: "Crucial preventative maintenance parts to save the N47 diesel block from its fatal flaws.", parts: [ { category: "Timing Chain Kit", brand: "Febi / INA", note: "CRITICAL: Replace entire rear cassette proactively to prevent engine death." }, { category: "Dual Mass Flywheel", brand: "LuK", note: "Replace if a loud metallic clattering is heard at idle." }, { category: "Glow Plugs & Module", brand: "Beru / Bosch", note: "Failed glow plugs will prevent the crucial DPF regeneration cycles." }, { category: "Vibration Damper (Crank Pulley)", brand: "Corteco / Gates", note: "Replace if rubber shows cracking; prevents belt shredding." }, { category: "Fuel Filter", brand: "Mann-Filter", note: "CRITICAL: Clean fuel is the only thing lubricating the fragile HPFP." }, { category: "DPF Differential Sensor", brand: "Bosch", note: "Prone to failure, causing false DPF clogged readings." }, { category: "EGR Cooler", brand: "Genuine BMW / Pierburg", note: "Replace immediately if losing coolant to prevent intake fires." }, { category: "Engine Oil Filter", brand: "Mann-Filter", note: "Use OEM quality only; frequent changes protect the timing chain." } ] },
