          automatics: [ { name: "8-Speed Steptronic (ZF 8HP50)", torqueLimit: "500 Nm", oilType: "ZF Lifeguard 8", note: "One of the best automatic transmissions ever made. Flawless, lightning-fast shifts. The 8HP50 handles tuned B47 torque easily. Perfectly suited for the longitudinal F22 layout. Requires strict fluid and filter pan replacement every 80,000 km." } ]
