        engineeringData: { blockDesign: "Closed-deck Aluminum alloy block with wire-arc sprayed iron cylinder linings. Part of the highly successful modular B-series family. Mounted longitudinally for the classic RWD layout. Features acoustic dampening to reduce diesel clatter significantly.", crankshaft: "Forged Steel, supported by 5 main bearings, highly robust.", pistonSpeed: "13.3 m/s @ 4000 RPM.", alternator: "150A Valeo.", rotatingAssembly: { pistonConstruction: "Cast Aluminum alloy with internal oil cooling galleries and a specialized combustion bowl in the crown.", wristPinDiameter: "26 mm.", connectingRodLength: "144 mm.", rodBoltSize: "M9 stretch bolts.", crankMainJournal: "55.0 mm.", crankRodJournal: "50.0 mm.", rodRatio: "1.66." }, cylinderHead: { combustionChamberVol: "Flat head design; combustion occurs entirely within the piston bowl.", intakePortFlow: "16-valve DOHC. Features highly efficient EGR routing integrated into the head and swirl flaps in the manifold.", valveSizes: "Intake: 27.2 mm / Exhaust: 24.6 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Fixed timing.", lifterType: "Hydraulic lifters with low-friction roller rockers.", specialFeature: "The timing chain is mounted at the REAR of the engine to save space, but unlike the N47, it rarely requires service." }, oilAndCooling: { oilSquirters: "Yes, dedicated high-pressure under-piston cooling jets.", oilPumpType: "Map-controlled variable volume gear pump.", thermostatOpening: "88°C Mechanical.", oilCooler: "Water-to-oil heat exchanger attached to the filter housing." }, fuelSystem: { systemType: "Bosch EDC17 Common Rail Direct Injection.", maxPressure: "2000 Bar (CP4.1 Pump).", injectors: "4x Solenoid Injectors (Highly reliable)." }, tuningLimits: { maxSafeTorqueStock: "480 Nm.", maxSafePowerStock: "240 hp.", maxSafeRPM: "4800 RPM.", weakestLink: "Dual Mass Flywheel, Factory Turbocharger flow limits, High-Pressure Fuel Pump (under poor lubrication)." }, electrical: { coils: "N/A (Compression Ignition).", ecu: "Bosch EDC17C50." } },
