          automatics: [ { name: "8-Speed Steptronic Sport (ZF 8HP45)", torqueLimit: "500 Nm", oilType: "ZF Lifeguard 8", note: "A robust, lightning-fast torque-converter automatic. Highly reliable, handles the twin-turbo torque flawlessly, provided the fluid and plastic filter pan are serviced strictly every 80k km." } ]
