          oilAndFilters: [ { interval: "10,000 km", timeLimit: "1 year", task: "Oil & Filter Change", details: "BMW Longlife-04 synthetic strictly. Critical for DPF health and extending the life of the fragile timing chain.", parts: ["5.2L Oil", "Mann-Filter"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "85 EUR" }, { interval: "30,000 km", timeLimit: "2 years", task: "Engine Air Filter", details: "Replace paper element.", parts: ["Air Filter"], importance: "High", laborDifficulty: "Easy", estimatedCost: "25 EUR" }, { interval: "30,000 km", timeLimit: "1 year", task: "Cabin Filter", details: "Activated carbon replacement.", parts: ["Cabin Filter"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "20 EUR" }, { interval: "30,000 km", timeLimit: "2 years", task: "Fuel Filter", details: "CRITICAL: Clean fuel is the only thing lubricating the high-pressure pump.", parts: ["Fuel Filter"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "45 EUR" } ],
          ignitionAndEngine: [ { interval: "80,000 km", timeLimit: "5 years", task: "Glow Plugs & Module", details: "Replace to ensure perfect cold starts and active DPF regens.", parts: ["4x Beru Plugs", "Module"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "150 EUR" }, { interval: "150,000 km", timeLimit: "Unlimited", task: "DPF Ash Cleaning", details: "Remove DPF and send for professional ash flushing.", parts: ["Exhaust Gaskets"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "400 EUR" }, { interval: "100,000 km", timeLimit: "Unlimited", task: "EGR & Intake Clean", details: "Remove intake manifold and clean EGR carbon sludge.", parts: ["Gaskets", "Cleaner"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "300 EUR" }, { interval: "150,000 km", timeLimit: "8 years", task: "Vibration Damper Check", details: "Inspect the main crank pulley for rubber cracking. Replace immediately to prevent belt shedding.", parts: ["Corteco Pulley"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "180 EUR" } ],
