          coolingAndHvac: [ { interval: "100,000 km", timeLimit: "5 years", task: "Coolant Flush", details: "Drain and refill G48 coolant.", parts: ["7.0L G48"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "60 EUR" }, { interval: "30,000 km", timeLimit: "Unlimited", task: "EGR Cooler Inspection", details: "CRITICAL: Inspect EGR cooler for internal coolant leaks (fire hazard). Covered under global BMW recall.", parts: ["Diagnostic"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "0 EUR" }, { interval: "4 Years", timeLimit: "4 years", task: "A/C Recharge", details: "Evacuate and recharge R134a.", parts: ["Refrigerant"], importance: "Medium", laborDifficulty: "Intermediate", estimatedCost: "80 EUR" }, { interval: "150,000 km", timeLimit: "10 years", task: "Water Pump & Thermostat", details: "Proactive replacement of the mechanical pump before bearings fail.", parts: ["Pump", "Thermostat"], importance: "Medium", laborDifficulty: "Advanced", estimatedCost: "250 EUR" } ],
          engineMechanical: [ { interval: "200,000 km", timeLimit: "Unlimited", task: "Injector Seals", details: "Replace copper crush washers to prevent combustion blow-by.", parts: ["Copper Seals"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "120 EUR" }, { interval: "250,000 km", timeLimit: "Unlimited", task: "Timing Chain Inspection", details: "The B47 chain is incredibly robust compared to the N47. Listen for cold start rattling at extreme high mileage.", parts: ["Diagnostic"], importance: "Low", laborDifficulty: "Easy", estimatedCost: "0 EUR" }, { interval: "150,000 km", timeLimit: "Unlimited", task: "Swirl Flap Delete", details: "Install blanking plates in the intake manifold to prevent ingestion.", parts: ["Blanking Kit"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "100 EUR" } ]
