          ignitionAndEngine: [ { interval: "30,000 km", timeLimit: "3 years", task: "Spark Plugs", details: "CRITICAL: Tuned S55s eat spark plugs rapidly. Replace frequently and gap to 0.022 inches.", parts: ["6x NGK Plugs"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "120 EUR" }, { interval: "60,000 km", timeLimit: "5 years", task: "Ignition Coils", details: "Proactive replacement of degrading coil packs to prevent severe boost misfires.", parts: ["6x Eldor Coils"], importance: "High", laborDifficulty: "Easy", estimatedCost: "250 EUR" }, { interval: "80,000 km", timeLimit: "6 years", task: "Walnut Blasting Carbon Clean", details: "CRITICAL: Physically clean carbon buildup from intake valves. Completely restores lost airflow and M-car throttle response.", parts: ["Intake Gaskets", "Walnut Media"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "350 EUR" }, { interval: "80,000 km", timeLimit: "6 years", task: "Oil Filter Housing Gasket", details: "CRITICAL: Proactively replace to prevent massive oil leaks. MUST PRIME OIL SYSTEM AFTERWARD VIA ISTA.", parts: ["Gaskets", "Alu Bolts"], importance: "Critical", laborDifficulty: "Expert", estimatedCost: "250 EUR" } ],
          preventiveAndSuspension: [ { interval: "100,000 km", timeLimit: "8 years", task: "Valve Cover Assembly", details: "Replace entire plastic valve cover due to failing internal PCV valve.", parts: ["Valve Cover", "Alu Bolts"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "450 EUR" }, { interval: "80,000 km", timeLimit: "6 years", task: "Serpentine Belt & Tensioner", details: "CRITICAL: Replace to prevent belt snapping and catastrophic engine ingestion.", parts: ["Belt", "Tensioner", "Idlers"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "160 EUR" }, { interval: "100,000 km", timeLimit: "8 years", task: "Front Control Arm Bushings", details: "Replace fluid-filled thrust arm bushings if leaking or torn, restoring sharp M steering.", parts: ["Bushings"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "180 EUR" }, { interval: "120,000 km", timeLimit: "8 years", task: "Strut Top Mounts", details: "Replace collapsed rubber mounts.", parts: ["Mounts & Bearings"], importance: "Medium", laborDifficulty: "Advanced", estimatedCost: "200 EUR" } ],
          coolingAndHvac: [ { interval: "30,000 km", timeLimit: "Unlimited", task: "TMIC Fluid Level Check", details: "CRITICAL: Frequently check the charge-air coolant reservoir. If the level drops, the TMIC is leaking internally into the engine.", parts: ["Diagnostic"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "0 EUR" }, { interval: "100,000 km", timeLimit: "5 years", task: "Coolant Flush (Both Circuits)", details: "Drain and refill G48 coolant in both the main engine and the charge-air cooler circuits.", parts: ["13.0L G48"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "100 EUR" }, { interval: "100,000 km", timeLimit: "7 years", task: "Electric Water Pump & T-Stat", details: "CRITICAL: Proactive replacement before sudden failure leaves you stranded on track.", parts: ["Pierburg Pump", "Thermostat"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "550 EUR" }, { interval: "4 Years", timeLimit: "4 years", task: "A/C Recharge", details: "Evacuate and recharge R1234yf.", parts: ["Refrigerant"], importance: "Medium", laborDifficulty: "Intermediate", estimatedCost: "120 EUR" } ],
          engineMechanical: [ { interval: "Immediately", timeLimit: "Unlimited", task: "Crank Hub Upgrade", details: "CRITICAL: Do not tune the car without pinning or splining the crank hub.", parts: ["1-Piece Hub Kit"], importance: "Critical", laborDifficulty: "Expert", estimatedCost: "1500 EUR" }, { interval: "Immediately", timeLimit: "Unlimited", task: "Aluminum Charge Pipe Install", details: "CRITICAL: Do not tune the car without replacing the plastic charge pipes.", parts: ["Aluminum Pipes"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "350 EUR" }, { interval: "150,000 km", timeLimit: "10 years", task: "Rod Bearing Preventative Service", details: "Highly recommended for tracked or aggressively tuned vehicles to prevent catastrophic failure.", parts: ["ACL Bearings", "Bolts", "Oil Pan Gasket"], importance: "Medium", laborDifficulty: "Expert", estimatedCost: "1200 EUR" }, { interval: "150,000 km", timeLimit: "Unlimited", task: "Valvetronic Actuator Calibration", details: "Run ISTA diagnostic routines to re-learn Valvetronic limit stops.", parts: ["Diagnostic"], importance: "Low", laborDifficulty: "Easy", estimatedCost: "0 EUR" } ]
