          automatics: [ { name: "7-Speed M Dual Clutch Transmission (M-DCT)", torqueLimit: "650 Nm", oilType: "Pentosin FFL-4", note: "The legendary M-DCT. Provides violently fast, uninterrupted gear changes perfectly suited for the track-focused CS. Capable of handling massive torque, but requires strict fluid and filter replacement every 60k km." } ]
