        engineeringData: { blockDesign: "Closed-deck Aluminum alloy block with wire-arc sprayed iron cylinder linings. The S55 is a true M-Division engine. The closed-deck architecture provides immense structural rigidity to handle the extreme cylinder pressures of the twin-turbo setup. The CS variant features a revised exhaust system and software map pushing it to 450hp.", crankshaft: "Forged Steel, exceptionally strong. However, the friction-washer design connecting the timing sprocket to the crank (the 'Crank Hub') is a massive engineering flaw.", pistonSpeed: "18.3 m/s @ 7000 RPM.", alternator: "180A Valeo.", rotatingAssembly: { pistonConstruction: "Forged Aluminum alloy pistons, specifically engineered for the S55 to handle extreme heat and pressure.", wristPinDiameter: "22 mm.", connectingRodLength: "144 mm.", rodBoltSize: "M9 stretch bolts.", crankMainJournal: "56.0 mm.", crankRodJournal: "50.0 mm.", rodRatio: "1.64." }, cylinderHead: { combustionChamberVol: "Optimized pent-roof design tailored for the 10.2:1 compression ratio.", intakePortFlow: "High-velocity tumble ports. The S55 utilizes Valvetronic, allowing the intake valves to act directly as the throttle for instantaneous M-car response.", valveSizes: "Intake: 32.0 mm / Exhaust: 28.0 mm.", valveStemDiameter: "5.0 mm.", camshaftDuration: "Double VANOS on both intake and exhaust camshafts, plus continuous Valvetronic lift control.", lifterType: "Hydraulic lifters with intermediate levers for Valvetronic.", specialFeature: "Utilizes a highly complex Air-to-Water Top Mount Intercooler (TMIC) integrated directly above the engine for zero intake lag." }, oilAndCooling: { oilSquirters: "Yes, dedicated high-flow under-piston cooling jets.", oilPumpType: "Map-controlled variable volume gear pump. Highly sensitive to air pockets; requires strict ISTA priming procedure.", thermostatOpening: "97°C Map-controlled electronic thermostat.", oilCooler: "External high-capacity air-to-oil cooler, dangerously mounted horizontally under the front bumper." }, fuelSystem: { systemType: "High-Pressure Direct Injection (HPI).", maxPressure: "200 Bar generated by TWO mechanical High-Pressure Fuel Pumps.", injectors: "6x Bosch Solenoid Injectors (Highly reliable)." }, tuningLimits: { maxSafeTorqueStock: "750 Nm.", maxSafePowerStock: "650 hp.", maxSafeRPM: "7600 RPM.", weakestLink: "Crank Hub (Catastrophic Failure), Plastic Charge Pipes, TMIC internal leaking, Factory Clutch (on manual models)." }, electrical: { coils: "Push-down 3-wire Active Coils.", ecu: "Bosch MEVD17.2.G." } },
        recommendedParts: { description: "Crucial preventative maintenance parts to maximize the lifespan and extreme track reliability of the S55 engine.", parts: [ { category: "Crank Hub Fix", brand: "Vargas / Insane", note: "CRITICAL: Pinned or splined one-piece hub. Mandatory before any tuning to prevent engine death." }, { category: "Aluminum Charge Pipes", brand: "VRSF / Mishimoto", note: "CRITICAL: Replaces the violently exploding factory plastic pipes." }, { category: "Top Mount Intercooler (TMIC)", brand: "CSF / Wagner", note: "CRITICAL: Replaces the factory intercooler to prevent internal coolant leaks and hydrolocking." }, { category: "Oil Filter Housing Gasket", brand: "Elring", note: "CRITICAL: Stops catastrophic oil leaks onto the serpentine belt." }, { category: "Ignition Coils", brand: "Eldor", note: "Upgrade to the latest revision for reliable high-boost performance." }, { category: "Spark Plugs", brand: "NGK 1-Step Colder (97506)", note: "Mandatory for tuned vehicles to prevent spark blowout." }, { category: "Valve Cover Kit", brand: "Genuine BMW", note: "Replace the entire plastic cover to cure internal PCV failure." }, { category: "Oil Cooler Skid Plate", brand: "Fall-Line Motorsports", note: "Protects the low-mounted oil cooler from road debris punctures." } ] },
