          automatics: [ { name: "6-Speed Aisin Automatic (AWF8F35 / TF-70SC)", torqueLimit: "300 Nm", oilType: "Aisin AW-1", note: "Early F45 218i models utilized a transverse 6-Speed Aisin automatic rather than the ZF 8-Speed. It provides smooth shifts tailored for comfort but requires strict fluid maintenance every 80,000 km." } ]
