          oilAndFilters: [ { interval: "10,000 km", timeLimit: "1 year", task: "Oil & Filter Change", details: "BMW Longlife-04 synthetic strictly. Frequent changes are critical for turbo bearing life and VANOS health.", parts: ["4.25L Oil", "Mann-Filter"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "75 EUR" }, { interval: "30,000 km", timeLimit: "2 years", task: "Engine Air Filter", details: "Replace paper element.", parts: ["Air Filter"], importance: "High", laborDifficulty: "Easy", estimatedCost: "25 EUR" }, { interval: "30,000 km", timeLimit: "1 year", task: "Cabin Filter", details: "Activated carbon replacement.", parts: ["Cabin Filter"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "30 EUR" }, { interval: "80,000 km", timeLimit: "5 years", task: "Fuel Filter", details: "Integrated in tank; replace if fuel pressure drops.", parts: ["Filter Unit"], importance: "Low", laborDifficulty: "Advanced", estimatedCost: "120 EUR" } ],
          ignitionAndEngine: [ { interval: "40,000 km", timeLimit: "4 years", task: "Spark Plugs", details: "Replace frequently, especially if the 218i is tuned.", parts: ["3x NGK Plugs"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "60 EUR" }, { interval: "60,000 km", timeLimit: "5 years", task: "Ignition Coils", details: "Proactive replacement of degrading coil packs to prevent boost misfires.", parts: ["3x Eldor Coils"], importance: "High", laborDifficulty: "Easy", estimatedCost: "120 EUR" }, { interval: "80,000 km", timeLimit: "6 years", task: "Walnut Blasting Carbon Clean", details: "Physically clean carbon buildup from intake valves. Completely restores lost airflow and cures 3-cylinder rough idle.", parts: ["Intake Gaskets", "Walnut Media"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "350 EUR" }, { interval: "80,000 km", timeLimit: "5 years", task: "Engine Mount Inspection", details: "Check fluid-filled mounts for weeping or collapse. The transverse 3-cylinder vibrations destroy them rapidly.", parts: ["Engine Mounts"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "250 EUR" } ],
