          automatics: [ { name: "7-Speed Dual Clutch (Magna 7DCT300)", torqueLimit: "300 Nm", oilType: "Pentosin FFL-4", note: "The LCI F45 models abandoned traditional automatics for a highly responsive 7-Speed Dual Clutch Transmission. It provides incredibly rapid shifts but requires strict fluid maintenance every 60,000 km to protect the complex clutch packs." } ]
