        engineeringData: { blockDesign: "Closed-deck Aluminum alloy block with wire-arc sprayed iron cylinder linings. The B37C15A engine is mounted Transversely, specifically for the Front-Wheel Drive architecture of the F45 Active Tourer. It features a heavy-duty balancer shaft to counteract the inherent primary vibrations of the 3-cylinder diesel layout.", crankshaft: "Forged Steel, supported by 4 main bearings, providing excellent durability for a small displacement engine.", pistonSpeed: "13.3 m/s @ 4000 RPM.", alternator: "150A Valeo.", rotatingAssembly: { pistonConstruction: "Cast Aluminum alloy with internal oil cooling galleries and a specialized combustion bowl in the crown.", wristPinDiameter: "26 mm.", connectingRodLength: "144 mm.", rodBoltSize: "M9 stretch bolts.", crankMainJournal: "50.0 mm.", crankRodJournal: "45.0 mm.", rodRatio: "1.66." }, cylinderHead: { combustionChamberVol: "Flat head design; combustion occurs entirely within the piston bowl.", intakePortFlow: "High-velocity tumble ports. Features highly efficient EGR routing integrated into the head and swirl flaps in the manifold.", valveSizes: "Intake: 27.2 mm / Exhaust: 24.6 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Fixed timing.", lifterType: "Hydraulic lifters with low-friction roller rockers.", specialFeature: "The timing chain is mounted at the REAR of the engine to save space, improving packaging for the transverse FWD layout." }, oilAndCooling: { oilSquirters: "Yes, dedicated high-pressure under-piston cooling jets.", oilPumpType: "Map-controlled variable volume gear pump.", thermostatOpening: "88°C Mechanical.", oilCooler: "Water-to-oil heat exchanger attached to the filter housing." }, fuelSystem: { systemType: "Bosch EDC17 Common Rail Direct Injection.", maxPressure: "2000 Bar (CP4.1 Pump).", injectors: "3x Solenoid Injectors (Highly reliable)." }, tuningLimits: { maxSafeTorqueStock: "350 Nm.", maxSafePowerStock: "170 hp.", maxSafeRPM: "4800 RPM.", weakestLink: "Fluid-Filled Engine Mounts, Factory Turbocharger flow limits, Dual Mass Flywheel." }, electrical: { coils: "N/A (Compression Ignition).", ecu: "Bosch EDC17C50." } },
